import csv
import sys

def mean_column(path, col):
    values = []
    with open(path) as f:
        reader = csv.DictReader(f)
        for row in reader:
            values.append(float(row[col]))
    return sum(values) / len(values)

if __name__ == '__main__':
    print(mean_column(sys.argv[1], sys.argv[2]))

